// Same saved-input repair must apply after a changed projection checkpoint.
// The installed legacy scorer is left intact; only its produced trend is corrected.
if(id==='inflation'){
 const {inflationR2AsOfTrendCompatibility}=await import('./inflation-r2-trend-date-refresh.mjs');
 const repaired=inflationR2AsOfTrendCompatibility(payload);
 if(repaired!==payload){
  await projectionWriter(core).write(id,repaired,Date.now(),checkpoint);
  report.projections.push({id,status:'LOCAL_READY'});
  return;
 }
}
